struct Lease final:spike::RecoveryLease{bool live{true};bool sustainedMode{true};spike::Ns end{spike::monotonic()+300000000000ULL};bool valid()const noexcept override{return live;}spike::Ns deadline()const noexcept override{return end;}bool stopRequested()const noexcept override{return !live;}spike::SustainedPolicy sustained()const noexcept override{return sustainedMode?spike::SustainedPolicy{1000000000ull,8,4096}:spike::SustainedPolicy{};}};
