struct Calls final:spike::VendorCalls{
 std::vector<std::uint32_t> pixels=std::vector<std::uint32_t>(underlay::Pixels,0xffffffffu);struct Request{spike::Rect rect;int content,mode,flags;};std::vector<Request> requests;unsigned acquired{},full{},partial{},quality{};spike::Rect last{};std::uint64_t largestFast{};Path railFile;int railAtFull{};Lease* revoke{};unsigned revokeAfter{};
 bool acquire(spike::Pixels& p)noexcept override{++acquired;p={reinterpret_cast<unsigned char*>(pixels.data()),1620,2160,4,6528};return true;}
 void region(spike::Rect r,int content,int mode,int flags)noexcept override{requests.push_back({r,content,mode,flags});last=r;if(revoke&&requests.size()==revokeAfter)revoke->live=false;if(flags!=0&&!(flags==1&&mode==3)&&!(flags==2&&mode==0))std::terminate();if(flags&1){++full;if(!railFile.empty()){std::ifstream in(railFile);in>>railAtFull;}if(r.x0||r.y0||r.x1!=1620||r.y1!=2160)std::terminate();if(content!=0||mode!=3)std::terminate();}else if((mode==3||mode==4)&&(content==0||content==1||content==3)){++quality;} /* UI or Content-mode (removal) regional quality */else if(content!=0||mode!=0)std::terminate();if(flags&1){}else{++partial;if(mode==0)largestFast=std::max(largestFast,std::uint64_t(r.x1-r.x0)*std::uint64_t(r.y1-r.y0));}}
 void events()noexcept override{}
 unsigned ghost{};std::size_t ghostAfter{};bool ghostClear()noexcept override{++ghost;ghostAfter=requests.size();return true;}
};
static Path application(const Path& source,const Path& data,const Path& build,const Path& sys){
 auto app=data/"application";underlay::privateDirectory(app/"assets/dictionary");std::filesystem::copy_file(source/"assets/dictionary/wordnet.ibd",app/"assets/dictionary/wordnet.ibd");underlay::privateDirectory(app/"bin");underlay::privateDirectory(app/"fixtures");
 std::filesystem::copy_file(source/"fixtures/inkbound-device-test.pdf",app/"fixtures/inkbound-device-test.pdf");
 std::filesystem::copy_file(source/"fixtures/dictionary-test.json",app/"fixtures/dictionary-test.json");
 std::filesystem::copy_file(build/"reader-experience1-prepare",app/"bin/helper-real");
 auto wrapper=QByteArray("#!/bin/sh\nexec '")+(sys/"usr/lib/ld-linux-aarch64.so.1").string().c_str()+"' --library-path '"+(sys/"usr/lib").string().c_str()+"' '"+(app/"bin/helper-real").string().c_str()+"' \"$@\"\n";
 underlay::atomicFile(app/"bin/reader-experience1-prepare",wrapper);CHECK(chmod((app/"bin/reader-experience1-prepare").c_str(),0700)==0);return app;
}
static library::Document importBook(const Path& app,const Path& source,const Path& root){
 QProcess process;process.start(QString::fromStdString((app/"bin/reader-experience1-prepare").string()),{"--import",QString::fromStdString((source/"fixtures/library/authored-three-pages.pdf").string()),QString::fromStdString(root.string())});
 CHECK(process.waitForStarted(2000)&&process.waitForFinished(30000)&&process.exitStatus()==QProcess::NormalExit&&process.exitCode()==0);auto docs=library::documents(root);CHECK(docs.size()==1&&docs[0].pages==3);return docs[0];
}
struct Harness {
 ux::Shell shell;Lease lease;Calls calls;spike::VendorDisplay vendor;ux::Display display;std::uint64_t version{};
 Harness(const Path& app,const Path& root,recovery::v2::sessionpower::SessionPower* power=nullptr):shell(app,root,true,false,false),vendor(calls),display(vendor,shell,nullptr,power){
  // Deliberately skip Display.initialize(): it opens real touch input. All tested
  // submit/readerBoundary paths are production code with touch fd left at -1.
  CHECK(vendor.initialize(lease)&&calls.acquired==1);CHECK(display.initialPage());version=display.pageVersion();CHECK(shell.choose(0));
  until([&]{boundary();CHECK(!shell.failed());return shell.writable();});CHECK(shell.styledInk());
 }
 void boundary(){CHECK(display.readerBoundary());if(display.pageVersion()!=version){version=display.pageVersion();display.pageInstalled();}}
 void settled(){until([&]{boundary();CHECK(!shell.failed());return shell.styledInk()->status().ready&&!shell.styledInk()->status().busy&&shell.styledInk()->damage().empty();});}
 void stroke(int x0,int y0,int x1,int y1,unsigned segments=1,bool hardwareEraser=false){
  // The Engine as the session builds it: the panel mapping with the display's input frame (a turned sheet's pixels).
  auto engine=std::make_unique<spike::Engine>(spike::engineTransform(spike::Transform{{0,1619},{0,2159},1620,2160,0,false},display),shell.ink(),display);
  CHECK(display.reserve());auto time=spike::monotonic();
  for(unsigned n=0;n<=segments+1;++n){unsigned step=std::min(n,segments);int x=x0+(x1-x0)*int(step)/int(segments),y=y0+(y1-y0)*int(step)/int(segments);auto phase=n==0?spike::Phase::Down:n==segments+1?spike::Phase::Up:spike::Phase::Move;
   spike::Sample sample{x,y,phase,time+n+1};sample.eraser=hardwareEraser;CHECK(engine->accept(sample));CHECK(display.append(engine->points().back()));CHECK(engine->flush()==spike::Submit::Accepted);
  }
 }
};

// UX scenario assertions use the production Shell -> Display -> VendorDisplay
// path, actual styled storage/rendering and a fake final vendor boundary.
// No real vendor module, input descriptor, provider, tablet or optical proof.
static QByteArray inkHash(ux::Shell& shell){auto pixels=shell.visibleInk();return underlay::digest(QByteArray(reinterpret_cast<const char*>(pixels.data()),qsizetype(pixels.size_bytes())));}
static bool overlap(spike::Rect a,spike::Rect b){return std::max(a.x0,b.x0)<std::min(a.x1,b.x1)&&std::max(a.y0,b.y0)<std::min(a.y1,b.y1);}
static std::vector<std::uint32_t> crop(const Calls& c,spike::Rect r){std::vector<std::uint32_t> p;for(int y=r.y0;y<r.y1;++y)for(int x=r.x0;x<r.x1;++x)p.push_back(c.pixels[std::size_t(y)*1632+x]);return p;}
static void settle(Harness& h){until([&]{h.boundary();CHECK(!h.shell.failed());return h.shell.unsaved()==0&&!h.shell.styledInk()->status().busy&&h.shell.styledInk()->status().ready&&!ux::DisplayTestAccess::pendingCleanup(h.display)&&!ux::DisplayTestAccess::removalDebt(h.display);});}
static void color(Harness& h,const char* name){bool found=false;for(unsigned i=0;i<8;++i)if(std::string_view(styled::colorId(i))==name){CHECK(h.shell.styledInk()->selectColor(i));found=true;break;}CHECK(found);settle(h);}
static bool regionalQuality(const Calls& c,spike::Rect r,int requiredContent=-1){for(const auto& q:c.requests)if((q.mode==3||q.mode==4)&&q.flags==0&&overlap(q.rect,r)&&(requiredContent<0||q.content==requiredContent))return true;return false;}
// The reader clock repaints itself when the minute turns (Shell::pollClock), independently of any scenario. Count-exact
// checks drop requests wholly inside the clock, at most one per window (one window never spans two minute turns).
static std::vector<Calls::Request> withoutClockTurn(const std::vector<Calls::Request>& in){std::vector<Calls::Request> out;unsigned clock=0;constexpr auto c=ib::status::ReaderClock;for(const auto& q:in){if(q.rect.x0>=c.x0&&q.rect.y0>=c.y0&&q.rect.x1<=c.x1&&q.rect.y1<=c.y1){++clock;continue;}out.push_back(q);}CHECK(clock<=1);return out;}
static void onlyRegional(const Calls& c){CHECK(!c.requests.empty());for(const auto& q:c.requests)CHECK(q.flags==0||(q.mode==0&&q.flags==2));}
static void seed(Harness& h){color(h,"black");h.stroke(300,900,450,900,5);settle(h);color(h,"red");h.stroke(320,1200,460,1200,5);settle(h);}
