  const auto accel=data/"turn-accel";std::filesystem::create_directories(accel);auto hold=[&](int x,int y){std::ofstream(accel/"in_accel_x_raw")<<x<<"\n";std::ofstream(accel/"in_accel_y_raw")<<y<<"\n";std::ofstream(accel/"in_accel_z_raw")<<0<<"\n";};
  hold(-1000,0);ux::TurnTestAccess::sensor(h.shell,accel); /* the top edge turned to the right */
  until([&]{h.boundary();CHECK(!h.shell.failed());return ux::TurnTestAccess::turn(h.shell)==ib::layout::Turn::Clockwise&&h.shell.writable();});settle(h);
  const auto turned=h.shell.document()->active().prepared.metadata;CHECK(turned["orientation"]==90&&turned["schema"]==3);
  const ib::layout::Frame f{ib::layout::Turn::Clockwise};const auto footer=ux::TurnTestAccess::clean(h.shell).rect(ib::reader::RevealZone);CHECK(footer.x0==f.physical({0,1520,2160,1620}).x0&&footer.x1==1620&&footer.y0==0&&footer.y1==2160);
  h.stroke(700,800,700,1200,5);settle(h); /* written along the reader's line, across the panel's height */
  auto map=[](const QJsonArray& m,double x,double y){return std::pair{m[0].toDouble()*x+m[2].toDouble()*y+m[4].toDouble(),m[1].toDouble()*x+m[3].toDouble()*y+m[5].toDouble()};};
  const auto source=map(turned["surfaceToPage"].toArray(),700,1000);
  hold(0,1000);until([&]{h.boundary();CHECK(!h.shell.failed());return ux::TurnTestAccess::turn(h.shell)==ib::layout::Turn::Portrait&&h.shell.writable();});settle(h);
  const auto upright=h.shell.document()->active().prepared.metadata;CHECK(!upright.contains("orientation"));
  const auto at=map(upright["pageToSurface"].toArray(),source.first,source.second);const spike::Rect area{int(at.first)-30,int(at.second)-30,int(at.first)+30,int(at.second)+30};
  h.shell.compose(h.vendor.surface(),area);unsigned dark=0;for(int y=area.y0;y<area.y1;++y)for(int x=area.x0;x<area.x1;++x)dark+=(h.calls.pixels[std::size_t(y)*1632+x]&0xffu)<96;CHECK(dark>20); /* the stroke shows where it was written */
