  h.stroke((close.x0+close.x1)/2,(close.y0+close.y1)/2,(close.x0+close.x1)/2,(close.y0+close.y1)/2);settle(h);CHECK(h.shell.semantics().view()==semantic::View::None&&storedStrokes(h,book.id)==strokes);
